function findCommonElements(arr1, arr2) {
  // Créer un tableau vide pour stocker les éléments communs
  let commonElements = [];

  // Boucler sur le premier tableau
  for (let I = 0; I < arr1.length; i++) {
    // Vérifier si l'élément est présent dans le deuxième tableau
    if (arr2.includes(arr1[i])) {
      // Ajouter l'élément commun au tableau des éléments communs
      commonElements.push(arr1[i]);
    }
  }

  // Retourner le tableau des éléments communs
  return commonElements;
}
